-- Pre-Built Assessments Migration
-- Stores pre-built assessment templates that recruiters can use

CREATE TABLE IF NOT EXISTS pre_built_assessments (
  id INT AUTO_INCREMENT PRIMARY KEY,
  title VARCHAR(255) NOT NULL,
  title_ar VARCHAR(255),
  description TEXT,
  description_ar TEXT,
  category ENUM('administrative', 'analytical', 'excel', 'coding', 'customer_service', 'communication', 'behavioral', 'personality', 'situational_judgment', 'job_simulation') NOT NULL,
  sub_category VARCHAR(100),
  difficulty_level ENUM('easy', 'medium', 'hard') DEFAULT 'medium',
  duration_minutes INT DEFAULT 30,
  num_questions INT DEFAULT 5,
  
  -- Assessment content stored as JSON
  questions JSON COMMENT 'Array of question objects with type, text, options, etc.',
  case_study_content JSON COMMENT 'Background, scenario, data if applicable',
  
  -- Metadata
  skills_tested JSON COMMENT 'Array of skill names',
  role_types JSON COMMENT 'Array of role types this is suitable for',
  industry VARCHAR(100),
  
  -- Stats
  times_used INT DEFAULT 0,
  avg_score DECIMAL(5,2),
  avg_completion_time_minutes INT,
  rating DECIMAL(3,2) DEFAULT 0,
  rating_count INT DEFAULT 0,
  
  -- Flags
  is_featured BOOLEAN DEFAULT FALSE,
  is_active BOOLEAN DEFAULT TRUE,
  requires_proctoring BOOLEAN DEFAULT FALSE,
  
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  
  INDEX idx_category (category),
  INDEX idx_difficulty (difficulty_level),
  INDEX idx_featured (is_featured),
  INDEX idx_active (is_active),
  FULLTEXT INDEX idx_search (title, description)
);

-- Junction table for recruiter's saved/favorite pre-built assessments
CREATE TABLE IF NOT EXISTS recruiter_saved_assessments (
  id INT AUTO_INCREMENT PRIMARY KEY,
  recruiter_id INT NOT NULL,
  pre_built_assessment_id INT NOT NULL,
  saved_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  
  FOREIGN KEY (recruiter_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (pre_built_assessment_id) REFERENCES pre_built_assessments(id) ON DELETE CASCADE,
  UNIQUE KEY unique_saved (recruiter_id, pre_built_assessment_id)
);

-- Table to track when pre-built assessments are published/used
CREATE TABLE IF NOT EXISTS published_pre_built_assessments (
  id INT AUTO_INCREMENT PRIMARY KEY,
  pre_built_assessment_id INT NOT NULL,
  recruiter_id INT NOT NULL,
  job_id INT,
  
  -- Customizations made by recruiter
  custom_title VARCHAR(255),
  custom_duration_minutes INT,
  custom_instructions TEXT,
  custom_questions JSON COMMENT 'Modified questions if any',
  
  -- Anti-cheating settings for this instance
  enable_fullscreen BOOLEAN DEFAULT FALSE,
  enable_tab_switch BOOLEAN DEFAULT FALSE,
  enable_copy_paste BOOLEAN DEFAULT FALSE,
  enable_screen_capture BOOLEAN DEFAULT FALSE,
  enable_webcam_proctoring BOOLEAN DEFAULT FALSE,
  max_tab_switches INT DEFAULT 3,
  
  -- Sharing
  share_token VARCHAR(64) UNIQUE,
  share_url VARCHAR(500),
  expires_at TIMESTAMP,
  
  -- Status
  status ENUM('draft', 'active', 'paused', 'closed') DEFAULT 'active',
  
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  
  FOREIGN KEY (pre_built_assessment_id) REFERENCES pre_built_assessments(id),
  FOREIGN KEY (recruiter_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (job_id) REFERENCES jobs(id) ON DELETE SET NULL,
  
  INDEX idx_recruiter (recruiter_id),
  INDEX idx_job (job_id),
  INDEX idx_share_token (share_token)
);

-- Seed some sample pre-built assessments with questions
INSERT INTO pre_built_assessments (title, title_ar, description, description_ar, category, difficulty_level, duration_minutes, num_questions, skills_tested, role_types, is_featured, questions, case_study_content) VALUES

-- Administrative
('Administrative Assistant Skills Test', 'اختبار مهارات المساعد الإداري', 'Comprehensive assessment of organizational, communication, and time management skills essential for administrative roles.', 'تقييم شامل للمهارات التنظيمية والتواصلية وإدارة الوقت الأساسية للأدوار الإدارية.', 'administrative', 'medium', 30, 5, '["Organization", "Communication", "Time Management", "MS Office", "Scheduling"]', '["Administrative Assistant", "Office Manager", "Executive Assistant"]', TRUE,
'[{"question": "Your manager has asked you to schedule a meeting with 5 department heads who all have conflicting schedules. How would you approach this task to find a suitable time slot?", "question_ar": "طلب منك مديرك جدولة اجتماع مع 5 رؤساء أقسام لديهم جداول متعارضة. كيف ستتعامل مع هذه المهمة لإيجاد وقت مناسب؟"}, {"question": "Describe how you would organize and maintain a filing system for both physical and digital documents in a busy office environment.", "question_ar": "صف كيف ستنظم وتحافظ على نظام أرشفة للوثائق المادية والرقمية في بيئة مكتب مزدحمة."}, {"question": "You receive multiple urgent requests from different executives at the same time. How do you prioritize and handle these competing demands?", "question_ar": "تتلقى عدة طلبات عاجلة من مديرين مختلفين في نفس الوقت. كيف تحدد الأولويات وتتعامل مع هذه المطالب المتنافسة؟"}, {"question": "An important client calls while your manager is in a meeting. The client seems frustrated about a delayed delivery. How would you handle this situation?", "question_ar": "يتصل عميل مهم بينما مديرك في اجتماع. يبدو العميل محبطًا بسبب تأخر التسليم. كيف ستتعامل مع هذا الموقف؟"}, {"question": "You notice that the office supply budget is being exceeded consistently. What steps would you take to address this issue?", "question_ar": "لاحظت أن ميزانية اللوازم المكتبية يتم تجاوزها باستمرار. ما الخطوات التي ستتخذها لمعالجة هذه المشكلة؟"}]',
'{"background": "You are an administrative assistant at a mid-sized consulting firm. The office supports 50 employees across 5 departments. Your responsibilities include managing calendars, handling correspondence, organizing files, and supporting executives.", "background_ar": "أنت مساعد إداري في شركة استشارية متوسطة الحجم. يدعم المكتب 50 موظفًا عبر 5 أقسام. تشمل مسؤولياتك إدارة التقويمات والتعامل مع المراسلات وتنظيم الملفات ودعم المديرين التنفيذيين."}'),

('Office Management Assessment', 'تقييم إدارة المكاتب', 'Evaluate candidate ability to manage office operations, coordinate activities, and handle multiple priorities.', 'تقييم قدرة المرشح على إدارة عمليات المكتب وتنسيق الأنشطة والتعامل مع أولويات متعددة.', 'administrative', 'medium', 25, 5, '["Office Management", "Coordination", "Problem Solving", "Communication"]', '["Office Manager", "Operations Coordinator"]', FALSE,
'[{"question": "How would you handle a situation where two team members are having a conflict that is affecting the office atmosphere?", "question_ar": "كيف ستتعامل مع موقف يكون فيه عضوان في الفريق في نزاع يؤثر على جو المكتب؟"}, {"question": "The office is relocating to a new building next month. What would be your plan to ensure a smooth transition?", "question_ar": "سينتقل المكتب إلى مبنى جديد الشهر القادم. ما خطتك لضمان انتقال سلس؟"}, {"question": "How would you implement a new office policy that you know will be unpopular with some staff members?", "question_ar": "كيف ستنفذ سياسة مكتبية جديدة تعلم أنها ستكون غير شعبية لدى بعض الموظفين؟"}, {"question": "Describe your approach to managing vendor relationships and negotiating contracts for office supplies and services.", "question_ar": "صف نهجك في إدارة علاقات الموردين والتفاوض على عقود اللوازم والخدمات المكتبية."}, {"question": "How would you handle an emergency situation in the office, such as a fire alarm or medical emergency?", "question_ar": "كيف ستتعامل مع حالة طوارئ في المكتب، مثل إنذار حريق أو حالة طوارئ طبية؟"}]',
'{"background": "You are the office manager for a growing tech startup with 75 employees. The company is expanding rapidly, and you are responsible for all office operations, facilities management, and administrative staff supervision.", "background_ar": "أنت مدير المكتب لشركة ناشئة تقنية متنامية تضم 75 موظفًا. الشركة تتوسع بسرعة وأنت مسؤول عن جميع عمليات المكتب وإدارة المرافق والإشراف على الموظفين الإداريين."}'),

-- Analytical
('Data Analysis Fundamentals', 'أساسيات تحليل البيانات', 'Test analytical thinking, data interpretation, and logical reasoning abilities.', 'اختبار التفكير التحليلي وتفسير البيانات وقدرات التفكير المنطقي.', 'analytical', 'medium', 45, 5, '["Data Analysis", "Critical Thinking", "Problem Solving", "Statistics"]', '["Data Analyst", "Business Analyst", "Research Analyst"]', TRUE,
'[{"question": "You are given a dataset showing declining sales over the past 6 months. What approach would you take to identify the root causes of this decline?", "question_ar": "تم إعطاؤك مجموعة بيانات تُظهر انخفاض المبيعات خلال الأشهر الستة الماضية. ما النهج الذي ستتبعه لتحديد الأسباب الجذرية لهذا الانخفاض؟"}, {"question": "How would you validate the accuracy and reliability of data before using it for analysis and decision-making?", "question_ar": "كيف ستتحقق من دقة وموثوقية البيانات قبل استخدامها للتحليل واتخاذ القرار؟"}, {"question": "A stakeholder asks you to present complex data findings to a non-technical audience. How would you approach this presentation?", "question_ar": "يطلب منك أحد أصحاب المصلحة تقديم نتائج بيانات معقدة لجمهور غير تقني. كيف ستتعامل مع هذا العرض؟"}, {"question": "You discover an outlier in your dataset that significantly affects your analysis results. How would you handle this situation?", "question_ar": "اكتشفت قيمة شاذة في مجموعة بياناتك تؤثر بشكل كبير على نتائج تحليلك. كيف ستتعامل مع هذا الموقف؟"}, {"question": "Describe how you would design a dashboard to track key performance indicators for a marketing department.", "question_ar": "صف كيف ستصمم لوحة معلومات لتتبع مؤشرات الأداء الرئيسية لقسم التسويق."}]',
'{"background": "You are a data analyst at an e-commerce company. The company has been experiencing fluctuating performance metrics, and leadership needs data-driven insights to make strategic decisions. You have access to sales data, customer behavior data, marketing spend data, and website analytics.", "background_ar": "أنت محلل بيانات في شركة تجارة إلكترونية. تعاني الشركة من تقلب مقاييس الأداء، وتحتاج القيادة إلى رؤى مبنية على البيانات لاتخاذ قرارات استراتيجية. لديك إمكانية الوصول إلى بيانات المبيعات وسلوك العملاء وإنفاق التسويق وتحليلات الموقع."}'),

('Logical Reasoning Assessment', 'تقييم التفكير المنطقي', 'Measure deductive and inductive reasoning skills through pattern recognition and logical problems.', 'قياس مهارات الاستدلال الاستنباطي والاستقرائي من خلال التعرف على الأنماط والمشكلات المنطقية.', 'analytical', 'hard', 40, 5, '["Logical Reasoning", "Pattern Recognition", "Problem Solving"]', '["Analyst", "Consultant", "Engineer"]', FALSE,
'[{"question": "A company notices that productivity increases when office temperature is between 68-72°F. They also notice productivity increases when employees take regular breaks. What can we logically conclude, and what additional information would help?", "question_ar": "لاحظت شركة أن الإنتاجية تزيد عندما تكون درجة حرارة المكتب بين 68-72 درجة فهرنهايت. كما لاحظوا أن الإنتاجية تزيد عندما يأخذ الموظفون فترات راحة منتظمة. ما الذي يمكننا استنتاجه منطقياً، وما المعلومات الإضافية التي ستساعد؟"}, {"question": "Three candidates applied for a position. Candidate A has 10 years of experience but no degree. Candidate B has a PhD but only 2 years of experience. Candidate C has 5 years of experience and a Masters degree. How would you approach this decision?", "question_ar": "تقدم ثلاثة مرشحين لوظيفة. المرشح أ لديه 10 سنوات خبرة بدون شهادة. المرشح ب لديه دكتوراه ولكن سنتان خبرة فقط. المرشح ج لديه 5 سنوات خبرة وماجستير. كيف ستتعامل مع هذا القرار؟"}, {"question": "If all successful projects have strong team communication, and Project X has strong team communication, what can we conclude about Project X?", "question_ar": "إذا كانت جميع المشاريع الناجحة لديها تواصل قوي بين الفريق، والمشروع X لديه تواصل قوي بين الفريق، ماذا يمكننا أن نستنتج عن المشروع X؟"}, {"question": "You observe that sales spike every Friday. What hypotheses would you generate, and how would you test them?", "question_ar": "لاحظت أن المبيعات ترتفع كل يوم جمعة. ما الفرضيات التي ستولدها، وكيف ستختبرها؟"}, {"question": "Describe a situation where correlation might be mistaken for causation and explain how you would investigate the true relationship.", "question_ar": "صف موقفًا قد يتم فيه الخلط بين الارتباط والسببية واشرح كيف ستحقق في العلاقة الحقيقية."}]',
'{"background": "You are a consultant working with various clients on strategic decision-making. Your role requires strong analytical and logical reasoning skills to help clients solve complex business problems.", "background_ar": "أنت مستشار تعمل مع عملاء مختلفين على اتخاذ القرارات الاستراتيجية. يتطلب دورك مهارات تحليلية ومنطقية قوية لمساعدة العملاء على حل مشاكل الأعمال المعقدة."}'),

-- Customer Service
('Customer Service Excellence', 'التميز في خدمة العملاء', 'Assess customer handling skills, empathy, problem resolution, and communication in service scenarios.', 'تقييم مهارات التعامل مع العملاء والتعاطف وحل المشكلات والتواصل في سيناريوهات الخدمة.', 'customer_service', 'medium', 30, 5, '["Customer Service", "Communication", "Problem Solving", "Empathy", "Conflict Resolution"]', '["Customer Service Rep", "Support Specialist", "Account Manager"]', TRUE,
'[{"question": "A customer is extremely upset because their order arrived damaged for the second time. They are threatening to leave negative reviews everywhere. How would you handle this situation?", "question_ar": "عميل غاضب للغاية لأن طلبه وصل تالفًا للمرة الثانية. يهدد بترك تقييمات سلبية في كل مكان. كيف ستتعامل مع هذا الموقف؟"}, {"question": "You realize that a company policy is causing repeated customer complaints, but you are not authorized to change it. What steps would you take?", "question_ar": "أدركت أن سياسة الشركة تسبب شكاوى متكررة من العملاء، لكنك غير مخول بتغييرها. ما الخطوات التي ستتخذها؟"}, {"question": "A customer is asking for a refund that falls outside your company standard return policy. How would you balance company policy with customer satisfaction?", "question_ar": "يطلب عميل استردادًا يقع خارج سياسة الإرجاع القياسية لشركتك. كيف ستوازن بين سياسة الشركة ورضا العملاء؟"}, {"question": "How would you handle a situation where you made a mistake that negatively impacted a customer?", "question_ar": "كيف ستتعامل مع موقف ارتكبت فيه خطأ أثر سلبًا على العميل؟"}, {"question": "A long-time loyal customer is considering switching to a competitor. How would you approach this conversation to retain them?", "question_ar": "يفكر عميل مخلص منذ فترة طويلة في التحول إلى منافس. كيف ستتعامل مع هذه المحادثة للاحتفاظ به؟"}]',
'{"background": "You work in the customer service department of a subscription-based software company. The company prides itself on excellent customer service, but has been experiencing some challenges with product quality recently. Your customer satisfaction score directly impacts your performance review.", "background_ar": "تعمل في قسم خدمة العملاء في شركة برمجيات قائمة على الاشتراكات. تفخر الشركة بخدمة العملاء الممتازة، لكنها واجهت بعض التحديات مع جودة المنتج مؤخرًا. تؤثر درجة رضا العملاء بشكل مباشر على تقييم أدائك."}'),

('Call Center Skills Assessment', 'تقييم مهارات مركز الاتصال', 'Evaluate phone etiquette, active listening, and ability to handle difficult customer situations.', 'تقييم آداب الهاتف والاستماع النشط والقدرة على التعامل مع مواقف العملاء الصعبة.', 'customer_service', 'easy', 25, 5, '["Phone Skills", "Active Listening", "De-escalation", "Product Knowledge"]', '["Call Center Agent", "Phone Support", "Telemarketer"]', FALSE,
'[{"question": "A customer calls and is speaking very quickly while describing a complex issue. How do you ensure you understand their problem correctly?", "question_ar": "يتصل عميل ويتحدث بسرعة كبيرة أثناء وصف مشكلة معقدة. كيف تتأكد من فهمك لمشكلته بشكل صحيح؟"}, {"question": "You need to put a customer on hold to check something. How would you handle this professionally?", "question_ar": "تحتاج إلى وضع العميل على الانتظار للتحقق من شيء ما. كيف ستتعامل مع هذا بشكل احترافي؟"}, {"question": "A customer keeps interrupting you while you are trying to explain the solution. How do you manage this conversation?", "question_ar": "يستمر العميل في مقاطعتك أثناء محاولتك شرح الحل. كيف تدير هذه المحادثة؟"}, {"question": "You do not know the answer to a customer question. What do you do?", "question_ar": "لا تعرف إجابة سؤال العميل. ماذا تفعل؟"}, {"question": "A customer is being verbally abusive on the phone. How would you handle this while maintaining professionalism?", "question_ar": "عميل يسيء شفهيًا على الهاتف. كيف ستتعامل مع هذا مع الحفاظ على الاحترافية؟"}]',
'{"background": "You are a call center representative for a telecommunications company. You handle approximately 50 calls per day covering billing inquiries, technical support, and general customer service. Call quality is monitored and average handling time is tracked.", "background_ar": "أنت ممثل مركز اتصال لشركة اتصالات. تتعامل مع حوالي 50 مكالمة يوميًا تغطي استفسارات الفواتير والدعم الفني وخدمة العملاء العامة. تتم مراقبة جودة المكالمات وتتبع متوسط وقت المعالجة."}'),

-- Communication
('Business Communication Skills', 'مهارات الاتصال التجاري', 'Test written and verbal communication abilities in professional business contexts.', 'اختبار قدرات الاتصال الكتابي والشفهي في سياقات الأعمال المهنية.', 'communication', 'medium', 35, 5, '["Business Writing", "Email Etiquette", "Presentation Skills", "Professional Communication"]', '["Any Professional Role", "Manager", "Sales", "Marketing"]', TRUE,
'[{"question": "Write a professional email to a client explaining a project delay and proposed new timeline.", "question_ar": "اكتب بريدًا إلكترونيًا احترافيًا لعميل تشرح فيه تأخير المشروع والجدول الزمني الجديد المقترح."}, {"question": "How would you communicate bad news to your team about budget cuts that will affect their projects?", "question_ar": "كيف ستنقل أخبارًا سيئة لفريقك حول تخفيضات الميزانية التي ستؤثر على مشاريعهم؟"}, {"question": "You need to persuade senior leadership to approve a new initiative. How would you structure your presentation?", "question_ar": "تحتاج إلى إقناع القيادة العليا بالموافقة على مبادرة جديدة. كيف ستهيكل عرضك التقديمي؟"}, {"question": "A colleague sends you an email with an angry tone. How would you respond professionally?", "question_ar": "يرسل لك زميل بريدًا إلكترونيًا بنبرة غاضبة. كيف سترد بشكل احترافي؟"}, {"question": "How would you explain a complex technical concept to a stakeholder with no technical background?", "question_ar": "كيف ستشرح مفهومًا تقنيًا معقدًا لصاحب مصلحة ليس لديه خلفية تقنية؟"}]',
'{"background": "You work in a corporate environment where effective communication is critical for success. You regularly interact with colleagues, clients, and leadership through various channels including email, presentations, and meetings.", "background_ar": "تعمل في بيئة مؤسسية حيث التواصل الفعال أمر حاسم للنجاح. تتفاعل بانتظام مع الزملاء والعملاء والقيادة من خلال قنوات مختلفة بما في ذلك البريد الإلكتروني والعروض التقديمية والاجتماعات."}'),

-- Behavioral  
('Workplace Behavior Assessment', 'تقييم السلوك في مكان العمل', 'Evaluate work ethics, teamwork, adaptability, and professional behavior tendencies.', 'تقييم أخلاقيات العمل والعمل الجماعي والقدرة على التكيف وميول السلوك المهني.', 'behavioral', 'medium', 25, 5, '["Teamwork", "Adaptability", "Work Ethics", "Professionalism"]', '["Any Role"]', TRUE,
'[{"question": "Describe a time when you had to adapt quickly to a significant change at work. How did you handle it?", "question_ar": "صف موقفًا اضطررت فيه للتكيف بسرعة مع تغيير كبير في العمل. كيف تعاملت معه؟"}, {"question": "Tell me about a situation where you disagreed with a team decision. How did you handle it?", "question_ar": "أخبرني عن موقف اختلفت فيه مع قرار الفريق. كيف تعاملت معه؟"}, {"question": "Describe a time when you went above and beyond your job responsibilities. What motivated you?", "question_ar": "صف موقفًا تجاوزت فيه مسؤوليات وظيفتك. ما الذي حفزك؟"}, {"question": "How do you handle stress and pressure in the workplace? Give a specific example.", "question_ar": "كيف تتعامل مع التوتر والضغط في مكان العمل؟ أعط مثالاً محددًا."}, {"question": "Describe your approach to receiving constructive criticism from a supervisor or colleague.", "question_ar": "صف نهجك في تلقي النقد البناء من مشرف أو زميل."}]',
'{"background": "This assessment evaluates your workplace behaviors and professional attitudes through situational questions. Your responses will help us understand how you approach work challenges, collaborate with others, and handle various professional situations.", "background_ar": "يقيم هذا التقييم سلوكياتك في مكان العمل ومواقفك المهنية من خلال أسئلة موقفية. ستساعدنا إجاباتك على فهم كيفية تعاملك مع تحديات العمل والتعاون مع الآخرين والتعامل مع المواقف المهنية المختلفة."}'),

('Leadership Potential Assessment', 'تقييم إمكانات القيادة', 'Identify leadership qualities, decision-making style, and team management potential.', 'تحديد الصفات القيادية وأسلوب صنع القرار وإمكانات إدارة الفريق.', 'behavioral', 'hard', 35, 5, '["Leadership", "Decision Making", "Team Management", "Strategic Thinking"]', '["Manager", "Team Lead", "Director", "Executive"]', TRUE,
'[{"question": "Your team is demoralized after a project failure. How would you lead them back to high performance?", "question_ar": "فريقك محبط بعد فشل مشروع. كيف ستقودهم للعودة إلى الأداء العالي؟"}, {"question": "You need to make a difficult decision that will benefit the company but negatively impact some team members. How would you approach this?", "question_ar": "تحتاج إلى اتخاذ قرار صعب سيفيد الشركة لكنه سيؤثر سلبًا على بعض أعضاء الفريق. كيف ستتعامل مع هذا؟"}, {"question": "Describe how you would develop and mentor a high-potential employee who is not reaching their full potential.", "question_ar": "صف كيف ستطور وتوجه موظفًا ذا إمكانات عالية لا يحقق إمكاناته الكاملة."}, {"question": "How would you handle a situation where two of your top performers are in conflict with each other?", "question_ar": "كيف ستتعامل مع موقف يكون فيه اثنان من أفضل أداء لديك في نزاع مع بعضهما البعض؟"}, {"question": "Describe your approach to making decisions with incomplete information and high uncertainty.", "question_ar": "صف نهجك في اتخاذ القرارات مع معلومات غير كاملة وعدم يقين عالي."}]',
'{"background": "This assessment evaluates your leadership capabilities through challenging scenarios that leaders commonly face. Your responses will reveal your leadership style, decision-making approach, and ability to inspire and develop others.", "background_ar": "يقيم هذا التقييم قدراتك القيادية من خلال سيناريوهات صعبة يواجهها القادة عادةً. ستكشف إجاباتك عن أسلوبك القيادي ونهجك في صنع القرار وقدرتك على إلهام الآخرين وتطويرهم."}'),

-- Job Simulation
('Project Manager Simulation', 'محاكاة مدير المشروع', 'Realistic project management scenarios including planning, risk assessment, and stakeholder communication.', 'سيناريوهات إدارة مشاريع واقعية تشمل التخطيط وتقييم المخاطر والتواصل مع أصحاب المصلحة.', 'job_simulation', 'hard', 60, 5, '["Project Planning", "Risk Management", "Stakeholder Management", "Agile/Waterfall"]', '["Project Manager", "Program Manager", "Scrum Master"]', TRUE,
'[{"question": "You have just been assigned to lead a project that is already 3 weeks behind schedule. What is your first 48-hour action plan?", "question_ar": "تم تعيينك للتو لقيادة مشروع متأخر بالفعل 3 أسابيع عن الجدول الزمني. ما خطة عملك لأول 48 ساعة؟"}, {"question": "A key team member informs you they are leaving the company in two weeks, right before a critical milestone. How do you mitigate this risk?", "question_ar": "يخبرك عضو رئيسي في الفريق أنه سيغادر الشركة خلال أسبوعين، قبل معلم حرج مباشرة. كيف تخفف من هذا الخطر؟"}, {"question": "The project sponsor wants to add significant new features without extending the deadline or budget. How would you handle this request?", "question_ar": "يريد راعي المشروع إضافة ميزات جديدة كبيرة دون تمديد الموعد النهائي أو الميزانية. كيف ستتعامل مع هذا الطلب؟"}, {"question": "You discover that two teams working on different parts of the project have been building components that are not compatible. What do you do?", "question_ar": "تكتشف أن فريقين يعملان على أجزاء مختلفة من المشروع كانا يبنيان مكونات غير متوافقة. ماذا تفعل؟"}, {"question": "How would you communicate project status to executive stakeholders who only have 5 minutes to hear your update?", "question_ar": "كيف ستنقل حالة المشروع إلى أصحاب المصلحة التنفيذيين الذين لديهم 5 دقائق فقط لسماع تحديثك؟"}]',
'{"background": "You are a senior project manager at a technology company. You manage complex software development projects with cross-functional teams of 15-20 people. Projects typically have budgets of $500K-$2M and durations of 6-12 months. You report to the VP of Engineering and work closely with Product, Design, and QA teams.", "background_ar": "أنت مدير مشروع أول في شركة تقنية. تدير مشاريع تطوير برمجيات معقدة مع فرق متعددة الوظائف من 15-20 شخصًا. عادةً ما يكون للمشاريع ميزانيات من 500 ألف إلى 2 مليون دولار ومدد من 6-12 شهرًا. تقدم تقاريرك إلى نائب رئيس الهندسة وتعمل بشكل وثيق مع فرق المنتج والتصميم وضمان الجودة."}'),

('Marketing Campaign Simulation', 'محاكاة حملة تسويقية', 'Create and analyze a marketing campaign with budget allocation, targeting, and ROI projections.', 'إنشاء وتحليل حملة تسويقية مع تخصيص الميزانية والاستهداف وتوقعات العائد على الاستثمار.', 'job_simulation', 'medium', 45, 5, '["Marketing Strategy", "Budget Management", "Analytics", "Creative Thinking"]', '["Marketing Manager", "Digital Marketer", "Brand Manager"]', TRUE,
'[{"question": "You have a $100,000 budget to launch a new product. How would you allocate this budget across different marketing channels and why?", "question_ar": "لديك ميزانية 100,000 دولار لإطلاق منتج جديد. كيف ستوزع هذه الميزانية عبر قنوات التسويق المختلفة ولماذا؟"}, {"question": "Your main competitor just launched an aggressive marketing campaign targeting your customer base. How would you respond?", "question_ar": "أطلق منافسك الرئيسي للتو حملة تسويقية عدوانية تستهدف قاعدة عملائك. كيف سترد؟"}, {"question": "A campaign you launched is underperforming. You are one week in with three weeks remaining. What metrics would you analyze and what adjustments would you consider?", "question_ar": "حملة أطلقتها لا تحقق الأداء المطلوب. أنت في الأسبوع الأول مع بقاء ثلاثة أسابيع. ما المقاييس التي ستحللها وما التعديلات التي ستفكر فيها؟"}, {"question": "How would you convince a skeptical CFO to increase the marketing budget for next quarter?", "question_ar": "كيف ستقنع مدير مالي متشكك بزيادة ميزانية التسويق للربع القادم؟"}, {"question": "Design a strategy to increase brand awareness for a B2B SaaS product among small business owners.", "question_ar": "صمم استراتيجية لزيادة الوعي بالعلامة التجارية لمنتج SaaS B2B بين أصحاب الأعمال الصغيرة."}]',
'{"background": "You are the Marketing Manager at a mid-sized SaaS company with 200 employees. The company sells productivity software to small and medium businesses. Your team consists of 5 people covering content, digital advertising, social media, and analytics. Annual marketing budget is $1.5M.", "background_ar": "أنت مدير التسويق في شركة SaaS متوسطة الحجم تضم 200 موظف. تبيع الشركة برامج إنتاجية للشركات الصغيرة والمتوسطة. يتكون فريقك من 5 أشخاص يغطون المحتوى والإعلان الرقمي ووسائل التواصل الاجتماعي والتحليلات. ميزانية التسويق السنوية 1.5 مليون دولار."}'),

('Financial Analysis Simulation', 'محاكاة التحليل المالي', 'Analyze financial statements, create projections, and make investment recommendations.', 'تحليل البيانات المالية وإنشاء التوقعات وتقديم توصيات الاستثمار.', 'job_simulation', 'hard', 50, 5, '["Financial Analysis", "Forecasting", "Investment Analysis", "Excel"]', '["Financial Analyst", "Investment Analyst", "FP&A"]', FALSE,
'[{"question": "A company shows increasing revenues but decreasing profit margins over the past 3 years. What would you investigate and what recommendations might you make?", "question_ar": "تُظهر شركة إيرادات متزايدة لكن هوامش ربح متناقصة خلال السنوات الثلاث الماضية. ما الذي ستحقق فيه وما التوصيات التي قد تقدمها؟"}, {"question": "You are evaluating two investment opportunities with similar returns but different risk profiles. How would you approach this comparison?", "question_ar": "أنت تقيم فرصتين استثماريتين بعوائد متشابهة لكن بمستويات مخاطر مختلفة. كيف ستتعامل مع هذه المقارنة؟"}, {"question": "The CEO asks for a 3-year financial projection for a new product line with no historical data. How would you approach building this forecast?", "question_ar": "يطلب الرئيس التنفيذي توقعات مالية لمدة 3 سنوات لخط منتجات جديد بدون بيانات تاريخية. كيف ستتعامل مع بناء هذه التوقعات؟"}, {"question": "You notice an anomaly in the accounts receivable aging report. Describe your investigation process.", "question_ar": "لاحظت شذوذًا في تقرير تقادم الذمم المدينة. صف عملية التحقيق الخاصة بك."}, {"question": "How would you present a financial analysis that recommends against a project that the executive team is enthusiastic about?", "question_ar": "كيف ستقدم تحليلاً ماليًا يوصي ضد مشروع يتحمس له الفريق التنفيذي؟"}]',
'{"background": "You are a Senior Financial Analyst at a manufacturing company with $50M in annual revenue. You report to the CFO and are responsible for financial planning, analysis, and supporting major business decisions. You work closely with operations, sales, and executive leadership.", "background_ar": "أنت محلل مالي أول في شركة تصنيع بإيرادات سنوية 50 مليون دولار. تقدم تقاريرك إلى المدير المالي وأنت مسؤول عن التخطيط المالي والتحليل ودعم قرارات الأعمال الرئيسية. تعمل بشكل وثيق مع العمليات والمبيعات والقيادة التنفيذية."}'),

('HR Case Study Simulation', 'محاكاة دراسة حالة الموارد البشرية', 'Handle realistic HR scenarios including hiring decisions, conflict resolution, and policy implementation.', 'التعامل مع سيناريوهات الموارد البشرية الواقعية بما في ذلك قرارات التوظيف وحل النزاعات وتنفيذ السياسات.', 'job_simulation', 'medium', 40, 5, '["HR Management", "Employee Relations", "Policy", "Compliance"]', '["HR Manager", "HR Business Partner", "Recruiter"]', FALSE,
'[{"question": "An employee files a complaint about their manager creating a hostile work environment. How would you investigate and address this situation?", "question_ar": "يقدم موظف شكوى بأن مديره يخلق بيئة عمل عدائية. كيف ستحقق في هذا الموقف وتعالجه؟"}, {"question": "Two equally qualified internal candidates are competing for the same promotion. How would you handle this situation fairly?", "question_ar": "مرشحان داخليان مؤهلان بنفس القدر يتنافسان على نفس الترقية. كيف ستتعامل مع هذا الموقف بإنصاف؟"}, {"question": "You need to implement a new policy that requires all employees to return to the office 3 days per week. Many employees are resistant. How would you manage this change?", "question_ar": "تحتاج إلى تنفيذ سياسة جديدة تتطلب من جميع الموظفين العودة إلى المكتب 3 أيام في الأسبوع. العديد من الموظفين يقاومون. كيف ستدير هذا التغيير؟"}, {"question": "A high performer has been consistently coming in late and their work quality has declined. How would you approach this situation?", "question_ar": "موظف عالي الأداء يأتي متأخرًا باستمرار وجودة عمله تراجعت. كيف ستتعامل مع هذا الموقف؟"}, {"question": "How would you design an onboarding program that effectively integrates new hires into the company culture?", "question_ar": "كيف ستصمم برنامج تأهيل يدمج الموظفين الجدد بفعالية في ثقافة الشركة؟"}]',
'{"background": "You are an HR Business Partner supporting 150 employees across three departments: Sales, Marketing, and Customer Success. The company is a fast-growing startup that recently went through a merger. You handle employee relations, performance management, talent development, and policy implementation.", "background_ar": "أنت شريك أعمال الموارد البشرية تدعم 150 موظفًا عبر ثلاثة أقسام: المبيعات والتسويق ونجاح العملاء. الشركة هي شركة ناشئة سريعة النمو مرت مؤخرًا بعملية دمج. تتعامل مع علاقات الموظفين وإدارة الأداء وتطوير المواهب وتنفيذ السياسات."}');

-- Additional seed entries added: Coding, Excel, Personality, Situational Judgment, Sales Simulation

INSERT INTO pre_built_assessments (title, title_ar, description, description_ar, category, difficulty_level, duration_minutes, num_questions, skills_tested, role_types, is_featured, questions, case_study_content) VALUES
('Full-Stack Coding Challenge', 'تحدي تطوير الويب الشامل', 'A hands-on coding assessment evaluating algorithmic problem solving, debugging, and system design under time constraints.', 'تقييم عملي للبرمجة يقيس حل المشكلات الخوارزمية وتصحيح الأخطاء وتصميم النظام تحت قيود زمنية.', 'coding', 'hard', 60, 5, '["JavaScript", "Algorithms", "Debugging", "System Design", "API"]', '["Full-Stack Developer", "Backend Engineer", "Software Engineer"]', TRUE,
'[{"question": "You are given a function that runs in O(n^2) on large inputs causing timeouts. Describe step-by-step how you would identify and optimize the hotspot.", "question_ar": "تم تزويدك بدالة تعمل بتعقيد زمني O(n^2) على مدخلات كبيرة وتسبب مهلات. صف خطوة بخطوة كيف ستحدد وتعمل على تحسين موقع الاختناق."}, {"question": "A user reports inconsistent API responses for a specific endpoint under high load. How would you debug and mitigate the issue in production?", "question_ar": "أبلغ مستخدم عن استجابات API غير متناسقة لنقطة نهاية معينة تحت حمل مرتفع. كيف ستقوم بتحري الخلل وتخفيف المشكلة في بيئة الإنتاج؟"}, {"question": "Design a simple schema for storing hierarchical categories and explain how you would query for all descendants efficiently.", "question_ar": "صمم مخططًا بسيطًا لتخزين الفئات الهرمية وشرح كيف ستستعلم عن جميع الأطفال بكفاءة."}, {"question": "Given a failing integration test that passes locally, outline the steps to reproduce and fix the failure considering environment differences.", "question_ar": "عند وجود اختبار تكامل فاشل ينجح محليًا، اذكر خطوات إعادة إنتاج الخطأ وإصلاحه مع مراعاة اختلافات البيئة."}, {"question": "Refactor the provided snippet to improve readability and reduce cyclomatic complexity (snippet included in test).", "question_ar": "أعد صياغة المقطع المقدم لتحسين قابلية القراءة وتقليل التعقيد الدوراني (سيتم تضمين المقطع في الاختبار)."}]',
'{"background": "You are a senior developer at a scale-up company building public APIs consumed by many clients. The system needs to be performant, maintainable, and resilient to partial failures.", "background_ar": "أنت مطور أول في شركة متنامية تبني واجهات برمجة تطبيقات عامة يستهلكها العديد من العملاء. يجب أن يكون النظام سريعًا وسهل الصيانة ومقاومًا للأخطاء الجزئية."}');

INSERT INTO pre_built_assessments (title, title_ar, description, description_ar, category, difficulty_level, duration_minutes, num_questions, skills_tested, role_types, is_featured, questions, case_study_content) VALUES
('Advanced Excel: Data Modeling & Pivot Analysis', 'Excel متقدم: نمذجة البيانات وتحليل Pivot', 'Assess candidate ability to build data models, use pivot tables, power functions, and perform analysis to extract business insights.', 'تقييم قدرة المرشح على بناء نماذج بيانات واستخدام جداول Pivot والدوال المتقدمة لإجراء تحليلات واستخراج رؤى تجارية.', 'excel', 'medium', 40, 5, '["Excel", "Pivot Tables", "VLOOKUP", "Power Query", "Data Modeling"]', '["Analyst", "Finance Associate", "Operations Analyst"]', TRUE,
'[{"question": "You are given a sales dataset with monthly transactions. Explain how you would create a pivot to show revenue by region and product category and identify the top 3 performers.", "question_ar": "تم تزويدك بمجموعة بيانات مبيعات مع معاملات شهرية. اشرح كيف ستنشئ Pivot تعرض الإيرادات حسب المنطقة وفئة المنتج وتحدد أفضل 3 أداء."}, {"question": "Describe a scenario where Power Query transforms are preferable to formulas and demonstrate a typical transform you would apply.", "question_ar": "صف سيناريو حيث تكون تحويلات Power Query مفضلة على الدوال وقدم مثالًا لتحويل نموذجي ستطبقه."}, {"question": "A formula returns #N/A when merging two tables - how do you troubleshoot and fix this issue?", "question_ar": "تعيد صيغة #N/A عند دمج جدولين - كيف تقوم بتحري الخلل وإصلاح المشكلة؟"}, {"question": "How would you model monthly subscription revenue to project churn-adjusted ARR for the next 12 months?", "question_ar": "كيف ستنموذج إيرادات الاشتراك الشهرية لتوقع ARR معدّلة حسب التسرب للأشهر الـ12 القادمة؟"}, {"question": "Explain when to use calculated fields vs measures in a pivot/power BI context.", "question_ar": "اشرح متى يجب استخدام الحقول المحسوبة مقابل القياسات في سياق Pivot/Power BI."}]',
'{"background": "You are an analyst supporting the finance team of a SaaS company. You regularly prepare dashboards and forecasts used by leadership for strategic decisions.", "background_ar": "أنت محلل تدعم فريق المالية في شركة SaaS. تقوم بإعداد لوحات بيانات وتوقعات يستخدمها القيادة لاتخاذ قرارات استراتيجية."}');

INSERT INTO pre_built_assessments (title, title_ar, description, description_ar, category, difficulty_level, duration_minutes, num_questions, skills_tested, role_types, is_featured, questions, case_study_content) VALUES
('Personality & Work Style Assessment', 'تقييم الشخصية وأسلوب العمل', 'A structured personality assessment to evaluate work preferences, collaboration style, and problem-solving approach.', 'تقييم منظم للشخصية لتقييم تفضيلات العمل، وأسلوب التعاون، ونهج حل المشكلات.', 'personality', 'easy', 25, 5, '["Personality", "Work Style", "Collaboration", "Decision Making"]', '["Any Role"]', FALSE,
'[{"question": "You prefer to work on a structured plan or adapt as new info comes in? Explain why and provide an example.", "question_ar": "هل تفضل العمل على خطة منظمة أم التكيف مع ورود معلومات جديدة؟ اشرح ولماذا وقدم مثالاً."}, {"question": "How do you handle disagreements with team members on approach to a shared task?", "question_ar": "كيف تتعامل مع الاختلافات مع أعضاء الفريق بشأن نهج مهمة مشتركة؟"}, {"question": "When faced with tight deadlines, how do you prioritize quality vs speed?", "question_ar": "عند مواجهة مواعيد نهائية ضيقة، كيف توازن بين الجودة والسرعة؟"}, {"question": "Describe a situation where you gave constructive feedback to a colleague successfully.", "question_ar": "صف موقفًا قدمت فيه ملاحظات بناءة لزميل بنجاح."}, {"question": "How do you learn best—reading, hands-on practice, or discussion? Provide an example of recent learning.", "question_ar": "كيف تتعلم بشكل أفضل - قراءة أم ممارسة عملية أم نقاش؟ قدم مثالًا على تعلم حديث."}]',
'{"background": "This assessment helps hiring teams understand candidate fit for team dynamics and role-specific behavioral expectations.", "background_ar": "يساعد هذا التقييم فرق التوظيف على فهم ملاءمة المرشح لديناميكيات الفريق وتوقعات السلوك المتعلقة بالدور."}');

INSERT INTO pre_built_assessments (title, title_ar, description, description_ar, category, difficulty_level, duration_minutes, num_questions, skills_tested, role_types, is_featured, questions, case_study_content) VALUES
('Situational Judgment: Ethical Dilemmas', 'حكم موقفي: المعضلات الأخلاقية', 'Measure decision-making and ethical judgment in workplace scenarios involving conflicting priorities.' , 'قياس اتخاذ القرار والحكم الأخلاقي في سيناريوهات مكان العمل التي تنطوي على تضارب في الأولويات.' , 'situational_judgment', 'medium', 30, 5, '["Ethics", "Decision Making", "Judgment", "Prioritization"]', '["Manager", "Team Lead", "HR"]', FALSE,
'[{"question": "You discover a colleague has been selectively reporting metrics to make their project look better. What steps would you take?", "question_ar": "تكتشف أن زميلًا يبلغ بشكل انتقائي عن المقاييس لجعل مشروعه يبدو أفضل. ما الخطوات التي ستتخذها؟"}, {"question": "A top customer threatens to leave unless you expedite a feature that compromises data privacy. How do you respond?", "question_ar": "هدد عميل مهم بالمغادرة ما لم نسرع ميزة تُعرض خصوصية البيانات للخطر. كيف سترد؟"}, {"question": "Two team members claim credit for the same idea causing conflict. How would you resolve and maintain fairness?", "question_ar": "يدعي عضوان في الفريق الفضل لنفس الفكرة مما يسبب صراعًا. كيف ستحل الأمر وتحافظ على العدالة؟"}, {"question": "You must choose between meeting a deadline and ensuring compliance testing — what do you prioritize and why?", "question_ar": "عليك الاختيار بين الالتزام بموعد نهائي وضمان اختبار الامتثال - ماذا تعطيه الأولوية ولماذا؟"}, {"question": "A senior manager asks you to hide a minor defect from stakeholders to protect a release. What do you do?", "question_ar": "يطلب منك مدير كبير إخفاء خلل بسيط عن أصحاب المصلحة لحماية الإصدار. ماذا تفعل؟"}]',
'{"background": "This assessment presents realistic workplace dilemmas to evaluate practical judgment and adherence to company values.", "background_ar": "يقدم هذا التقييم معضلات واقعية في مكان العمل لتقييم الحكم العملي والالتزام بقيم الشركة."}');

INSERT INTO pre_built_assessments (title, title_ar, description, description_ar, category, difficulty_level, duration_minutes, num_questions, skills_tested, role_types, is_featured, questions, case_study_content) VALUES
('Sales Negotiation Simulation', 'محاكاة تفاوض المبيعات', 'Simulate a high-stakes sales negotiation including pricing, concessions, and long-term relationship building.', 'محاكاة تفاوض مبيعات عالي المخاطر تشمل التسعير والتنازلات وبناء العلاقات طويلة الأمد.', 'job_simulation', 'medium', 40, 5, '["Negotiation", "Sales", "Communication", "Commercial Acumen"]', '["Account Executive", "Sales Manager", "Business Development"]', TRUE,
'[{"question": "A key prospect pushes for an aggressive discount that would hurt margins. How do you negotiate to protect value while keeping the deal alive?", "question_ar": "يطالب عميل مهم بتخفيض قوي سيضر بالهوامش. كيف تتفاوض لحماية القيمة مع الحفاظ على إتمام الصفقة؟"}, {"question": "The prospect requests a multi-year contract but wants added features not in scope. How do you balance scope, pricing, and timeline?", "question_ar": "يطلب العميل عقدًا متعدد السنوات لكنه يريد ميزات إضافية غير مدرجة في النطاق. كيف توازن بين النطاق والتسعير والجدول الزمني؟"}, {"question": "A stakeholder insists on custom integration that increases implementation risk. What alternatives do you propose?", "question_ar": "يصر صاحب المصلحة على تكامل مخصص يزيد من مخاطر التنفيذ. ما البدائل التي تقترحها؟"}, {"question": "How would you debrief your internal team after a lost negotiation to improve future outcomes?", "question_ar": "كيف ستقوم بإحاطة فريقك الداخلي بعد تفاوض خاسر لتحسين النتائج المستقبلية؟"}, {"question": "Describe how you would identify and escalate red flags during a negotiation to senior leadership.", "question_ar": "صف كيف ستحدد وترفع أعلام التحذير أثناء التفاوض إلى القيادة العليا."}]',
'{"background": "This simulation reflects realistic enterprise B2B sales scenarios where negotiation skill and commercial judgment are critical.", "background_ar": "تعكس هذه المحاكاة سيناريوهات مبيعات B2B حقيقية حيث تكون مهارة التفاوض والحكم التجاري أمرًا بالغ الأهمية."}');

